CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name shown on assignments and comments.
	"full_name" VARCHAR(160) NOT NULL,
	-- Profile image URL.
	"avatar_url" VARCHAR(500),
	-- IANA zone. Due-date reminders and daily digests are sent in local time.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- False when someone leaves. Their issues and comments keep their attribution.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who can be assigned work. Deactivated rather than deleted, because every issue they touched still references them.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name shown on assignments and comments.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Profile image URL.';
COMMENT ON COLUMN "users"."timezone" IS 'IANA zone. Due-date reminders and daily digests are sent in local time.';
COMMENT ON COLUMN "users"."is_active" IS 'False when someone leaves. Their issues and comments keep their attribution.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "projects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short uppercase prefix, e.g. WEB. Combined with a per-project counter it forms the human issue key WEB-142.
	"key" VARCHAR(10) NOT NULL UNIQUE,
	-- Project name.
	"name" VARCHAR(160) NOT NULL,
	-- What the project covers.
	"description" TEXT,
	-- Project lead. Null while unassigned.
	"lead_id" BIGINT,
	-- active | paused | archived. Archived projects are read-only.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- Last issue number allocated in this project. Incremented under the row lock that also inserts the issue.
	"issue_counter" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "projects" IS 'A container for work. The key plus a per-project counter is what gives issues a short memorable identifier that people can say out loud.';
COMMENT ON COLUMN "projects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "projects"."key" IS 'Short uppercase prefix, e.g. WEB. Combined with a per-project counter it forms the human issue key WEB-142.';
COMMENT ON COLUMN "projects"."name" IS 'Project name.';
COMMENT ON COLUMN "projects"."description" IS 'What the project covers.';
COMMENT ON COLUMN "projects"."lead_id" IS 'Project lead. Null while unassigned.';
COMMENT ON COLUMN "projects"."status" IS 'active | paused | archived. Archived projects are read-only.';
COMMENT ON COLUMN "projects"."issue_counter" IS 'Last issue number allocated in this project. Incremented under the row lock that also inserts the issue.';
COMMENT ON COLUMN "projects"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "project_members" (
	-- Project joined. Half of the composite primary key.
	"project_id" BIGINT,
	-- Member. The other half of the key.
	"user_id" BIGINT,
	-- admin | member | viewer. Decides who can move issues and edit settings.
	"role" VARCHAR(20) NOT NULL DEFAULT 'member',
	-- When the member was added.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("project_id", "user_id")
);

COMMENT ON TABLE "project_members" IS 'Membership and per-project role. The composite key makes duplicate membership impossible, and the reverse index answers "which projects am I in".';
COMMENT ON COLUMN "project_members"."project_id" IS 'Project joined. Half of the composite primary key.';
COMMENT ON COLUMN "project_members"."user_id" IS 'Member. The other half of the key.';
COMMENT ON COLUMN "project_members"."role" IS 'admin | member | viewer. Decides who can move issues and edit settings.';
COMMENT ON COLUMN "project_members"."added_at" IS 'When the member was added.';

CREATE INDEX "idx_project_members_user"
ON "project_members" ("user_id");

CREATE TABLE IF NOT EXISTS "milestones" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Milestone or sprint name.
	"name" VARCHAR(120) NOT NULL,
	-- Goal of the milestone.
	"description" TEXT,
	-- Start date, for sprints.
	"starts_on" DATE,
	-- Target completion date. Drives burndown and overdue reporting.
	"due_on" DATE,
	-- When it was closed.
	"completed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "milestones" IS 'A dated bucket of work — a sprint, a release, a phase. Kept separate from issue status so an issue can move between milestones without losing its progress.';
COMMENT ON COLUMN "milestones"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "milestones"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "milestones"."name" IS 'Milestone or sprint name.';
COMMENT ON COLUMN "milestones"."description" IS 'Goal of the milestone.';
COMMENT ON COLUMN "milestones"."starts_on" IS 'Start date, for sprints.';
COMMENT ON COLUMN "milestones"."due_on" IS 'Target completion date. Drives burndown and overdue reporting.';
COMMENT ON COLUMN "milestones"."completed_at" IS 'When it was closed.';

CREATE INDEX "idx_milestones_project_due"
ON "milestones" ("project_id", "due_on");

CREATE TABLE IF NOT EXISTS "issues" (
	-- Surrogate primary key used by foreign keys.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Per-project sequence number. Combined with the project key it renders as WEB-142.
	"number" INTEGER NOT NULL,
	-- Parent issue, making this a subtask. One level of nesting is what most teams actually use.
	"parent_issue_id" BIGINT,
	-- Milestone the issue is scheduled into. Null for the backlog.
	"milestone_id" BIGINT,
	-- Issue summary.
	"title" VARCHAR(300) NOT NULL,
	-- Full description, Markdown.
	"description" TEXT,
	-- task | bug | story | epic.
	"issue_type" VARCHAR(20) NOT NULL DEFAULT 'task',
	-- todo | in_progress | in_review | done | cancelled. A fixed vocabulary keeps board queries simple; configurable workflows need their own table.
	"status" VARCHAR(24) NOT NULL DEFAULT 'todo',
	-- low | medium | high | urgent.
	"priority" VARCHAR(12) NOT NULL DEFAULT 'medium',
	-- Who raised it.
	"reporter_id" BIGINT,
	-- Who owns it now. Null means unassigned, which is a real and common state.
	"assignee_id" BIGINT,
	-- Relative estimate in story points.
	"estimate_points" INTEGER,
	-- Sort key within a board column. A fractional position lets a drag-and-drop reorder update one row instead of renumbering the column.
	"board_position" NUMERIC(20,10),
	-- Due date, as a local date rather than an instant.
	"due_on" DATE,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last change, used for recently-updated views.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the issue reached a terminal status. Kept for cycle-time reporting.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "issues" IS 'The unit of work. Subtasks are the same entity through parent_issue_id rather than a separate table, so filters, permissions and notifications apply uniformly.';
COMMENT ON COLUMN "issues"."id" IS 'Surrogate primary key used by foreign keys.';
COMMENT ON COLUMN "issues"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "issues"."number" IS 'Per-project sequence number. Combined with the project key it renders as WEB-142.';
COMMENT ON COLUMN "issues"."parent_issue_id" IS 'Parent issue, making this a subtask. One level of nesting is what most teams actually use.';
COMMENT ON COLUMN "issues"."milestone_id" IS 'Milestone the issue is scheduled into. Null for the backlog.';
COMMENT ON COLUMN "issues"."title" IS 'Issue summary.';
COMMENT ON COLUMN "issues"."description" IS 'Full description, Markdown.';
COMMENT ON COLUMN "issues"."issue_type" IS 'task | bug | story | epic.';
COMMENT ON COLUMN "issues"."status" IS 'todo | in_progress | in_review | done | cancelled. A fixed vocabulary keeps board queries simple; configurable workflows need their own table.';
COMMENT ON COLUMN "issues"."priority" IS 'low | medium | high | urgent.';
COMMENT ON COLUMN "issues"."reporter_id" IS 'Who raised it.';
COMMENT ON COLUMN "issues"."assignee_id" IS 'Who owns it now. Null means unassigned, which is a real and common state.';
COMMENT ON COLUMN "issues"."estimate_points" IS 'Relative estimate in story points.';
COMMENT ON COLUMN "issues"."board_position" IS 'Sort key within a board column. A fractional position lets a drag-and-drop reorder update one row instead of renumbering the column.';
COMMENT ON COLUMN "issues"."due_on" IS 'Due date, as a local date rather than an instant.';
COMMENT ON COLUMN "issues"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "issues"."updated_at" IS 'Last change, used for recently-updated views.';
COMMENT ON COLUMN "issues"."closed_at" IS 'When the issue reached a terminal status. Kept for cycle-time reporting.';

CREATE UNIQUE INDEX "uq_issues_project_number"
ON "issues" ("project_id", "number");
CREATE INDEX "idx_issues_board"
ON "issues" ("project_id", "status", "board_position");
CREATE INDEX "idx_issues_assignee_status"
ON "issues" ("assignee_id", "status");
CREATE INDEX "idx_issues_milestone_status"
ON "issues" ("milestone_id", "status");

CREATE TABLE IF NOT EXISTS "labels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project. Labels are per project, so two teams can both have "urgent" without agreeing on a colour.
	"project_id" BIGINT NOT NULL,
	-- Label text.
	"name" VARCHAR(60) NOT NULL,
	-- Hex colour used in the UI.
	"color" VARCHAR(7) NOT NULL DEFAULT '#64748b',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "labels" IS 'Free-form categorisation that is cheaper than adding a column every time a team invents a new axis.';
COMMENT ON COLUMN "labels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "labels"."project_id" IS 'Owning project. Labels are per project, so two teams can both have "urgent" without agreeing on a colour.';
COMMENT ON COLUMN "labels"."name" IS 'Label text.';
COMMENT ON COLUMN "labels"."color" IS 'Hex colour used in the UI.';

CREATE UNIQUE INDEX "uq_labels_project_name"
ON "labels" ("project_id", "name");

CREATE TABLE IF NOT EXISTS "issue_labels" (
	-- Issue labelled. Half of the composite primary key.
	"issue_id" BIGINT,
	-- Label applied. The other half of the key.
	"label_id" BIGINT,
	-- When the label was applied.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("issue_id", "label_id")
);

COMMENT ON TABLE "issue_labels" IS 'Many-to-many join with nothing to say beyond existence, so the pair is the primary key.';
COMMENT ON COLUMN "issue_labels"."issue_id" IS 'Issue labelled. Half of the composite primary key.';
COMMENT ON COLUMN "issue_labels"."label_id" IS 'Label applied. The other half of the key.';
COMMENT ON COLUMN "issue_labels"."added_at" IS 'When the label was applied.';

CREATE INDEX "idx_issue_labels_label"
ON "issue_labels" ("label_id");

CREATE TABLE IF NOT EXISTS "issue_comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Issue being discussed.
	"issue_id" BIGINT NOT NULL,
	-- Comment author. Null if the account was deleted outright.
	"author_id" BIGINT,
	-- Comment text, Markdown.
	"body" TEXT NOT NULL,
	-- Submission time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit, shown as edited in the UI.
	"edited_at" TIMESTAMP,
	-- Soft deletion, so the discussion keeps its shape.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "issue_comments" IS 'Discussion on an issue. Always read in issue order, which is exactly what the composite index provides.';
COMMENT ON COLUMN "issue_comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "issue_comments"."issue_id" IS 'Issue being discussed.';
COMMENT ON COLUMN "issue_comments"."author_id" IS 'Comment author. Null if the account was deleted outright.';
COMMENT ON COLUMN "issue_comments"."body" IS 'Comment text, Markdown.';
COMMENT ON COLUMN "issue_comments"."created_at" IS 'Submission time.';
COMMENT ON COLUMN "issue_comments"."edited_at" IS 'Last edit, shown as edited in the UI.';
COMMENT ON COLUMN "issue_comments"."deleted_at" IS 'Soft deletion, so the discussion keeps its shape.';

CREATE INDEX "idx_issue_comments_issue_created"
ON "issue_comments" ("issue_id", "created_at");

CREATE TABLE IF NOT EXISTS "attachments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Issue the file belongs to.
	"issue_id" BIGINT NOT NULL,
	-- Uploader.
	"uploaded_by_id" BIGINT,
	-- Object storage key. The database stores the pointer, not the bytes.
	"storage_key" VARCHAR(500) NOT NULL UNIQUE,
	-- Original filename shown in the UI.
	"filename" VARCHAR(255) NOT NULL,
	-- Content type, used to decide inline preview versus download.
	"mime_type" VARCHAR(100) NOT NULL,
	-- File size in bytes, for quota accounting.
	"byte_size" BIGINT NOT NULL,
	-- Upload time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "attachments" IS 'Files attached to an issue. Attaching to the issue rather than to a comment means a file survives the comment being deleted.';
COMMENT ON COLUMN "attachments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "attachments"."issue_id" IS 'Issue the file belongs to.';
COMMENT ON COLUMN "attachments"."uploaded_by_id" IS 'Uploader.';
COMMENT ON COLUMN "attachments"."storage_key" IS 'Object storage key. The database stores the pointer, not the bytes.';
COMMENT ON COLUMN "attachments"."filename" IS 'Original filename shown in the UI.';
COMMENT ON COLUMN "attachments"."mime_type" IS 'Content type, used to decide inline preview versus download.';
COMMENT ON COLUMN "attachments"."byte_size" IS 'File size in bytes, for quota accounting.';
COMMENT ON COLUMN "attachments"."created_at" IS 'Upload time.';

CREATE INDEX "idx_attachments_issue"
ON "attachments" ("issue_id");

CREATE TABLE IF NOT EXISTS "time_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Issue the time was spent on.
	"issue_id" BIGINT NOT NULL,
	-- Who spent it.
	"user_id" BIGINT NOT NULL,
	-- Duration in minutes. Integers avoid the rounding arguments that decimal hours cause.
	"minutes" INTEGER NOT NULL,
	-- The day the work happened, which is often not the day it was logged.
	"spent_on" DATE NOT NULL,
	-- What was done.
	"note" VARCHAR(255),
	-- When the entry was logged.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "time_entries" IS 'Worklog rows rather than a running total on the issue. Timesheets, invoicing and per-person reporting all need the individual entries; a total can always be summed.';
COMMENT ON COLUMN "time_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "time_entries"."issue_id" IS 'Issue the time was spent on.';
COMMENT ON COLUMN "time_entries"."user_id" IS 'Who spent it.';
COMMENT ON COLUMN "time_entries"."minutes" IS 'Duration in minutes. Integers avoid the rounding arguments that decimal hours cause.';
COMMENT ON COLUMN "time_entries"."spent_on" IS 'The day the work happened, which is often not the day it was logged.';
COMMENT ON COLUMN "time_entries"."note" IS 'What was done.';
COMMENT ON COLUMN "time_entries"."created_at" IS 'When the entry was logged.';

CREATE INDEX "idx_time_entries_user_date"
ON "time_entries" ("user_id", "spent_on");
CREATE INDEX "idx_time_entries_issue_date"
ON "time_entries" ("issue_id", "spent_on");

